  UPDATE topics SET slides = $s$[{"t": "title", "title": "9-amaliy: Matritsalar", "subtitle": "Jadvallar bilan ishlaymiz", "emoji": "🔲"}, {"t": "idea", "title": "Kinoteatr zali", "text": "Kinoteatrda o'rinlar qator va joy raqami bilan belgilanadi: 5-qator, 12-joy. Band o'rinlar sxemasi — aynan matritsa: `zal[qator][joy]`.", "emoji": "🎬"}, {"t": "code", "title": "Zal sxemasi", "code": "zal = [[\".\" for _ in range(6)] for _ in range(4)]\nzal[1][2] = \"X\"\nzal[3][5] = \"X\"\nfor q in zal:\n    print(\" \".join(q))\nprint(\"Band:\", sum(q.count(\"X\") for q in zal))", "output": ". . . . . .\n. . X . . .\n. . . . . .\n. . . . . X\nBand: 2"}, {"t": "code", "title": "Kiritish va ustunlar yig'indisi", "code": "n, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\nfor j in range(m):\n    print(sum(a[i][j] for i in range(n)), end=\" \")\nprint()", "input": "2 3\n1 2 3\n4 5 6", "output": "5 7 9 "}, {"t": "code", "title": "Qo'shnilarni tekshirish", "code": "a = [[1, 2, 3],\n     [4, 5, 6],\n     [7, 8, 9]]\ni, j = 0, 0\nq = []\nfor di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:\n    ni, nj = i + di, j + dj\n    if 0 <= ni < 3 and 0 <= nj < 3:\n        q.append(a[ni][nj])\nprint(q)", "output": "[4, 2]", "note": "Burchakdagi kataning faqat 2 ta qo'shnisi bor — chegarani tekshirish shart."}, {"t": "compare", "title": "Chegarani tekshirmaslik", "left": {"label": "Manfiy indeks jim turib oxirgi qatorni oladi", "code": "a = [[1, 2], [3, 4]]\nprint(a[0 - 1][0])   # 3 — xato emas, lekin noto'g'ri!"}, "right": {"label": "Tekshirish", "code": "ni = -1\nif 0 <= ni < 2:\n    print(a[ni][0])"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["6", "12", "15", "45"], "answer": 2, "explain": "Bosh diagonal: 1 + 5 + 9 = 15.", "code": "a = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]\nprint(sum(a[i][i] for i in range(3)))"}, {"t": "task", "title": "Eng katta qator", "text": "n×m matritsani o'qing va yig'indisi eng katta bo'lgan qator raqamini (1 dan) chiqaring.", "starter": "n, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]", "hint": "`sums = [sum(q) for q in a]`, keyin `sums.index(max(sums)) + 1`"}, {"t": "summary", "title": "Matritsa bilan ishlash", "items": ["Yaratish: `[[0]*m for _ in range(n)]`", "Satr: `a[i]`, element: `a[i][j]`, ustun — sikl bilan", "Qo'shnilar: `(-1,0), (1,0), (0,-1), (0,1)` siljishlar", "Chegarani doim tekshiring — manfiy indeks xato bermaydi"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'amaliy-9-matritsa';
