  UPDATE topics SET slides = $s$[{"t": "title", "title": "10-amaliy: Rekursiya", "subtitle": "Masalani o'ziga o'xshash kichik masalaga keltiramiz", "emoji": "🌀"}, {"t": "idea", "title": "Navbatdagi odamga so'rash", "text": "Uzun navbatda turibsiz va nechanchi ekaningizni bilmoqchisiz. Oldingizdagidan so'raysiz, u ham o'zidan oldingisidan... Birinchi odam \"men birinchiman\" deydi va javoblar orqaga qaytadi.", "emoji": "🧍"}, {"t": "points", "title": "Rekursiya yozish rejasi", "items": [{"e": "1️⃣", "text": "Eng kichik holat qanday va javobi nima?"}, {"e": "2️⃣", "text": "Masalani qanday qilib bir qadam kichraytirish mumkin?"}, {"e": "3️⃣", "text": "Kichik javobdan katta javobni qanday yig'amiz?"}]}, {"t": "code", "title": "Ro'yxat yig'indisi", "code": "def yigindi(a):\n    if not a:\n        return 0\n    return a[0] + yigindi(a[1:])\n\nprint(yigindi([3, 5, 2, 10]))", "output": "20"}, {"t": "code", "title": "EKUB — Yevklid", "code": "def ekub(a, b):\n    if b == 0:\n        return a\n    return ekub(b, a % b)\n\nprint(ekub(48, 18), ekub(17, 5))", "output": "6 1"}, {"t": "code", "title": "Barcha variantlar", "code": "def satrlar(n, s=\"\"):\n    if n == 0:\n        print(s)\n        return\n    satrlar(n - 1, s + \"0\")\n    satrlar(n - 1, s + \"1\")\n\nsatrlar(2)", "output": "00\n01\n10\n11"}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["3 2 1", "1", "3", "1 2 3"], "answer": 3, "explain": "`print` rekursiv chaqiruvdan KEYIN — eng ichkisi birinchi chiqaradi.", "code": "def f(n):\n    if n == 0:\n        return\n    f(n - 1)\n    print(n, end=\" \")\n\nf(3)"}, {"t": "task", "title": "Ikkilik sanoq (rekursiv)", "text": "Sonni ikkilik sanoq sistemasiga rekursiya bilan o'tkazing (`bin()` ishlatmang).", "starter": "def ikkilik(n):\n    ...\n\nprint(ikkilik(10))", "hint": "`if n < 2: return str(n)`, aks holda `ikkilik(n // 2) + str(n % 2)`"}, {"t": "summary", "title": "Rekursiya amaliyoti", "items": ["Avval asosiy holatni yozing", "Har chaqiruvda masala kichrayishi shart", "Chaqiruvdan keyingi kod — teskari tartibda bajariladi", "Variantlarni sanab chiqish — rekursiyaning kuchli tomoni"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'amaliy-10-rekursiya';
