  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "11-amaliy: Saralash va qidiruv", "subtitle": "Algoritmni o'zimiz yozamiz", "emoji": "📶"}, {"t": "idea", "title": "Karta o'yinchisi", "text": "O'yinchi kartalarni qo'liga birma-bir oladi va har birini **o'z joyiga** qo'yadi. Bu — qo'shib saralash (insertion sort). Deyarli tartiblangan qo'lda u juda tez.", "emoji": "🃏"}, {"t": "code", "title": "Qo'shib saralash", "code": "def qoshib(a):\n    a = a[:]\n    for i in range(1, len(a)):\n        x = a[i]\n        j = i - 1\n        while j >= 0 and a[j] > x:\n            a[j + 1] = a[j]\n            j -= 1\n        a[j + 1] = x\n    return a\n\nprint(qoshib([5, 2, 9, 1, 7, 3]))", "output": "[1, 2, 3, 5, 7, 9]"}, {"t": "code", "title": "Pufakcha — almashtirishlarni sanash", "code": "a = [4, 3, 2, 1]\nalmashtirish = 0\nfor i in range(len(a) - 1):\n    for j in range(len(a) - 1 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n            almashtirish += 1\nprint(a, almashtirish)", "output": "[1, 2, 3, 4] 6"}, {"t": "code", "title": "bisect — tayyor ikkilik qidiruv", "code": "import bisect\nballar = [55, 60, 71, 80, 92]\njoy = bisect.bisect_left(ballar, 75)\nballar.insert(joy, 75)\nprint(joy, ballar)", "output": "3 [55, 60, 71, 75, 80, 92]"}, {"t": "compare", "title": "Asl ro'yxatni buzib qo'yish", "left": {"label": "Funksiya asl ro'yxatni o'zgartiradi", "code": "def sarala(a):\n    a.sort()\n    return a\n\nx = [3, 1, 2]\ny = sarala(x)\nprint(x)   # [1, 2, 3] — asl ham o'zgardi"}, "right": {"label": "Nusxa bilan", "code": "def sarala(a):\n    return sorted(a)\n\nx = [3, 1, 2]\ny = sarala(x)\nprint(x)   # [3, 1, 2]"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["1", "3", "25", "2"], "answer": 3, "explain": "25 ni tartib buzilmasdan qo'yish uchun joy — 2-indeks (20 va 30 orasi).", "code": "import bisect\nprint(bisect.bisect_left([10, 20, 30], 25))"}, {"t": "task", "title": "Tanlab saralash", "text": "Tanlab saralashni (selection sort) yozing: har qadamda qolgan qismdan eng kichigini topib, o'z joyiga qo'ying.", "starter": "a = [64, 25, 12, 22, 11]\nfor i in range(len(a)):\n    k = i\n    ...\nprint(a)", "hint": "Ichki sikl: `for j in range(i + 1, len(a)): if a[j] < a[k]: k = j`, keyin almashtiring."}, {"t": "summary", "title": "Algoritmlar amaliyoti", "items": ["Qo'shib saralash — deyarli tartiblangan ma'lumotda tez", "Pufakcha — eng sodda, lekin eng sekin", "`bisect` — tartiblangan ro'yxatga joy topish", "Funksiya asl ro'yxatni buzmasin — `sorted()` yoki nusxa"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'amaliy-11-algoritmlar';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: amaliy-11-algoritmlar'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "12-amaliy: Sinflar va obyektlar", "subtitle": "O'z ma'lumot turimizni yaratamiz", "emoji": "🧬"}, {"t": "idea", "title": "Kutubxona kartochkasi", "text": "Har bir kitobning kartochkasi bor: nomi, muallifi, kimda ekani. Kitob berilganda kartochkada belgi qo'yiladi.\n\nSinf — kartochka shakli, har bir kitob — undan yaratilgan obyekt.", "emoji": "📚"}, {"t": "code", "title": "Kitob sinfi", "code": "class Kitob:\n    def __init__(self, nom, sahifa):\n        self.nom = nom\n        self.sahifa = sahifa\n        self.oqilgan = 0\n\n    def oqi(self, n):\n        self.oqilgan = min(self.sahifa, self.oqilgan + n)\n\n    def __str__(self):\n        return f\"{self.nom}: {self.oqilgan * 100 // self.sahifa}%\"\n\nk = Kitob(\"O'tkan kunlar\", 400)\nk.oqi(150)\nk.oqi(70)\nprint(k)", "output": "O'tkan kunlar: 55%"}, {"t": "code", "title": "Obyektlar ro'yxati", "code": "class Talaba:\n    def __init__(self, ism, ball):\n        self.ism, self.ball = ism, ball\n\nguruh = [Talaba(\"Ali\", 87), Talaba(\"Vali\", 92), Talaba(\"Zarina\", 78)]\nfor t in sorted(guruh, key=lambda t: t.ball, reverse=True):\n    print(t.ism, t.ball)", "output": "Vali 92\nAli 87\nZarina 78"}, {"t": "code", "title": "Meros va super()", "code": "class Xodim:\n    def __init__(self, ism, maosh):\n        self.ism, self.maosh = ism, maosh\n    def oylik(self):\n        return self.maosh\n\nclass Rahbar(Xodim):\n    def __init__(self, ism, maosh, bonus):\n        super().__init__(ism, maosh)\n        self.bonus = bonus\n    def oylik(self):\n        return super().oylik() + self.bonus\n\nprint(Rahbar(\"Vali\", 8_000_000, 2_000_000).oylik())", "output": "10000000"}, {"t": "compare", "title": "Atributni self'siz yozish", "left": {"label": "Lokal o'zgaruvchi — obyektda saqlanmaydi", "code": "class A:\n    def __init__(self, x):\n        x = x   # self yo'q!\n\nprint(A(5).x)   # AttributeError"}, "right": {"label": "self bilan", "code": "class A:\n    def __init__(self, x):\n        self.x = x\n\nprint(A(5).x)"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["RecursionError", "1", "11", "10"], "answer": 2, "explain": "B.f ota sinf natijasini (1) olib, 10 qo'shadi.", "code": "class A:\n    def f(self):\n        return 1\n\nclass B(A):\n    def f(self):\n        return super().f() + 10\n\nprint(B().f())"}, {"t": "task", "title": "Bank hisobi", "text": "`Hisob` sinfini yozing: `toldir(s)` va `yech(s)` metodlari bilan. Mablag' yetmasa, `yech` \"Rad etildi\" deb chiqarsin va balansni o'zgartirmasin.", "starter": "class Hisob:\n    def __init__(self):\n        self.balans = 0\n\nh = Hisob()\nh.toldir(100)\nh.yech(30)\nh.yech(100)\nprint(h.balans)", "hint": "Kutilgan natija: \"Rad etildi\" va 70."}, {"t": "summary", "title": "Sinflar amaliyoti", "items": ["Atributlar doim `self.` bilan saqlanadi", "`__str__` — `print(obyekt)` uchun chiroyli matn", "Obyektlarni `key=lambda o: o.atribut` bilan saralash", "`super()` — ota sinf kodini qayta ishlatish"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'amaliy-12-sinflar';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: amaliy-12-sinflar'; END IF;
  v_jami := v_jami + v_n;

  RAISE NOTICE 'Taqdimot qo''shildi: % ta mavzu', v_jami;
END $$;
